SOURCES.VoidWingsAssets = [===[
--[[
	Void Wings image ids. Upload assets/voidwings/*.png (Studio > View > Asset
	Manager > Bulk Import, or tools/voidwings/upload.py) and paste each image
	id below. Until the feather atlases are filled in, the wings draw as plain
	neon blades so the rig can still be checked.

	FeatherR_n: right-wing atlases (feather_R_n.png), FeatherL_n: left-wing
	atlases (feather_L_n.png). Each is 2x2 frames; together the 16-frame loop.

	If the galaxy loop stutters (frames playing out of order), Roblox is
	tiling the atlas from a different corner on your build: flip
	FrameFlipU and/or FrameFlipV until it flows smoothly.
]]

return {
	FeatherR_0 = "",
	FeatherR_1 = "",
	FeatherR_2 = "",
	FeatherR_3 = "",
	FeatherL_0 = "",
	FeatherL_1 = "",
	FeatherL_2 = "",
	FeatherL_3 = "",
	Sparkle = "",
	Mote = "",
	Wisp = "",

	FrameFlipU = false,
	FrameFlipV = false,
}
]===]

SOURCES.Preview = [===[
--[[
	Shop / inventory preview: a dummy wearing the real cosmetic inside a
	ViewportFrame, slowly orbiting so the wings are seen from behind and both
	sides.

		local handle = Preview.mount(viewportFrame, "VoidWings")
		handle:SetItem("VoidWings") -- or nil for the bare dummy
		handle:Destroy()

	The dummy is a copy of the local player's character when it can be
	cloned, otherwise a blocky R6 dummy.
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Items = require(script.Parent.Items)

local Preview = {}

local function blockyDummy(): Model
	local model = Instance.new("Model")
	model.Name = "PreviewDummy"
	local skin = Color3.fromRGB(165, 200, 230)
	local cloth = Color3.fromRGB(24, 36, 70)
	local function add(name, size, cframe, color)
		local part = Instance.new("Part")
		part.Name = name
		part.Size = size
		part.CFrame = cframe
		part.Color = color
		part.Anchored = true
		part.CanCollide = false
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		part.Parent = model
		return part
	end
	local torso = add("Torso", Vector3.new(2, 2, 1), CFrame.new(0, 3, 0), cloth)
	add("Head", Vector3.new(2, 1, 1), CFrame.new(0, 4.5, 0), skin)
	add("Left Arm", Vector3.new(1, 2, 1), CFrame.new(-1.5, 3, 0), skin)
	add("Right Arm", Vector3.new(1, 2, 1), CFrame.new(1.5, 3, 0), skin)
	add("Left Leg", Vector3.new(1, 2, 1), CFrame.new(-0.5, 1, 0), cloth)
	add("Right Leg", Vector3.new(1, 2, 1), CFrame.new(0.5, 1, 0), cloth)
	model.PrimaryPart = torso
	return model
end

local function characterCopy(): Model?
	local character = Players.LocalPlayer and Players.LocalPlayer.Character
	if not character then
		return nil
	end
	local ok, copy = pcall(function()
		local was = character.Archivable
		character.Archivable = true
		local clone = character:Clone()
		character.Archivable = was
		return clone
	end)
	if not ok or not copy then
		return nil
	end
	for _, d in ipairs(copy:GetDescendants()) do
		if d:IsA("BaseScript") or d:IsA("ModuleScript") or d:IsA("Sound") or d:IsA("ParticleEmitter")
			or d:IsA("Light") or d.Name == "VoidWings" or d.Name == "VoidWingsLight" then
			d:Destroy()
		elseif d:IsA("BasePart") then
			d.Anchored = true
			d.CanCollide = false
		elseif d:IsA("Humanoid") then
			d.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
		end
	end
	if not (copy:FindFirstChild("Torso") or copy:FindFirstChild("UpperTorso")) then
		copy:Destroy()
		return nil
	end
	return copy
end

function Preview.mount(viewport: ViewportFrame, itemId: string?)
	local folder = Instance.new("Folder")
	folder.Name = "CosmeticPreview"
	folder.Parent = viewport

	local camera = Instance.new("Camera")
	camera.FieldOfView = 38
	camera.Parent = folder
	viewport.CurrentCamera = camera
	viewport.Ambient = Color3.fromRGB(150, 140, 180)
	viewport.LightColor = Color3.fromRGB(255, 245, 255)
	viewport.LightDirection = Vector3.new(-0.4, -1, -0.6)

	local dummy = characterCopy() or blockyDummy()
	dummy.Name = "PreviewDummy"
	dummy:PivotTo(CFrame.new(0, 3, 0))
	dummy.Parent = folder
	local torso = (dummy:FindFirstChild("Torso") or dummy:FindFirstChild("UpperTorso")) :: BasePart
	local focus = torso.Position + Vector3.new(0, 1.2, 0)

	local handle = { Rig = nil, Id = nil }

	function handle:SetItem(id: string?)
		if handle.Rig then
			handle.Rig:Destroy()
			handle.Rig = nil
		end
		handle.Id = id
		local item = Items.get(id)
		local module = item and item.Rig and script.Parent:FindFirstChild(item.Rig)
		if module then
			handle.Rig = require(module).new(torso, { Viewport = true, Parent = folder })
		end
	end

	local start = os.clock()
	local connection = RunService.RenderStepped:Connect(function()
		if not viewport.Visible then
			return
		end
		local t = os.clock() - start
		-- orbit around the back: +Z is behind the dummy
		local yaw = math.sin(t * 0.45) * 1.05
		local offset = CFrame.Angles(0, yaw, 0) * Vector3.new(0, 1.6, 16)
		camera.CFrame = CFrame.lookAt(focus + offset, focus)
		if handle.Rig then
			handle.Rig:Step(os.clock())
		end
	end)

	function handle:Destroy()
		connection:Disconnect()
		if handle.Rig then
			handle.Rig:Destroy()
		end
		folder:Destroy()
	end

	handle:SetItem(itemId)
	return handle
end

return Preview
]===]

SOURCES.CosmeticsServer = [===[
--[[
	Cosmetics ownership and equipping (server-authoritative).

	Ownership: exclusive items are granted by name/UserId in Items.Catalog
	(Void Wings -> merreystantach2). Nothing is sold or tradeable, so grants
	are the only source. The server publishes:
		player:GetAttribute("OwnedCosmetics")  -- "VoidWings,..."
		player:GetAttribute("EquippedWings")   -- item id or nil
	Clients render whatever is equipped (CosmeticsClient), so wearing costs
	no replication beyond one attribute.

	Equip choices persist in a DataStore. A granted item the player has never
	taken off is worn by default.
]]

local DataStoreService = game:GetService("DataStoreService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Items = require(ReplicatedStorage:WaitForChild("Cosmetics"):WaitForChild("Items"))

local remote = ReplicatedStorage:FindFirstChild("CosmeticsRemote")
if not remote then
	remote = Instance.new("RemoteEvent")
	remote.Name = "CosmeticsRemote"
	remote.Parent = ReplicatedStorage
end

local store
pcall(function()
	store = DataStoreService:GetDataStore("SDCO_Cosmetics_v1")
end)

local owned: { [Player]: { [string]: boolean } } = {}
local saved: { [Player]: { [string]: string } } = {}
local dirty: { [Player]: boolean } = {}
local lastRequest: { [Player]: number } = {}

local function key(player: Player)
	return "u_" .. player.UserId
end

local function load(player: Player): { [string]: string }?
	if not store then
		return nil
	end
	local ok, data = pcall(function()
		return store:GetAsync(key(player))
	end)
	return if ok and type(data) == "table" then data else nil
end

local function save(player: Player)
	if not (store and dirty[player] and saved[player]) then
		return
	end
	dirty[player] = nil
	local data = table.clone(saved[player])
	local ok, err = pcall(function()
		store:SetAsync(key(player), data, { player.UserId })
	end)
	if not ok then
		warn("[Cosmetics] save failed for " .. player.Name .. ": " .. tostring(err))
	end
end

local function wear(player: Player, slot: string, id: string?)
	player:SetAttribute("Equipped" .. slot, id)
end

local function setup(player: Player)
	if owned[player] then
		return
	end
	local list = Items.grantedTo(player)
	local set = {}
	for _, id in ipairs(list) do
		set[id] = true
	end
	owned[player] = set
	player:SetAttribute("OwnedCosmetics", table.concat(list, ","))

	saved[player] = {}
	local data = load(player) or {}
	if not owned[player] then
		return -- left while loading
	end
	for slot, id in pairs(saved[player]) do
		data[slot] = id -- a choice made while the store was loading wins
	end
	saved[player] = data
	for _, slot in ipairs(Items.Slots) do
		local choice = data[slot]
		if choice == nil then
			-- never chosen: wear the first owned item for this slot
			for _, id in ipairs(list) do
				if Items.Catalog[id].Category == slot then
					choice = id
					break
				end
			end
		end
		wear(player, slot, if choice and choice ~= "" and set[choice] then choice else nil)
	end
end

remote.OnServerEvent:Connect(function(player: Player, action, id)
	local now = os.clock()
	if lastRequest[player] and now - lastRequest[player] < 0.25 then
		return
	end
	lastRequest[player] = now
	local set = owned[player]
	if not set then
		return
	end

	if action == "Equip" and type(id) == "string" then
		local item = Items.get(id)
		if item and set[id] then
			wear(player, item.Category, id)
			saved[player][item.Category] = id
			dirty[player] = true
		end
	elseif action == "Unequip" and type(id) == "string" then
		if table.find(Items.Slots, id) then
			wear(player, id, nil)
			saved[player][id] = "" -- remember the choice, so the default doesn't come back
			dirty[player] = true
		end
	end
end)

Players.PlayerAdded:Connect(setup)
for _, player in ipairs(Players:GetPlayers()) do
	task.spawn(setup, player)
end

Players.PlayerRemoving:Connect(function(player)
	save(player)
	owned[player] = nil
	saved[player] = nil
	dirty[player] = nil
	lastRequest[player] = nil
end)

game:BindToClose(function()
	for _, player in ipairs(Players:GetPlayers()) do
		task.spawn(save, player)
	end
	task.wait(2)
end)
]===]

SOURCES.CosmeticsClient = [===[
--[[
	Renders equipped cosmetics on every character (client-side rigs, driven
	from one RenderStepped) and the local inventory panel with a live
	ViewportFrame preview.
]]

local ContentProvider = game:GetService("ContentProvider")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Cosmetics = ReplicatedStorage:WaitForChild("Cosmetics")
local Items = require(Cosmetics:WaitForChild("Items"))
local Preview = require(Cosmetics:WaitForChild("Preview"))
local remote = ReplicatedStorage:WaitForChild("CosmeticsRemote")

local player = Players.LocalPlayer
local CULL_DISTANCE = 220

local function rigModule(item)
	local module = item and item.Rig and Cosmetics:FindFirstChild(item.Rig)
	return module and require(module)
end

-- preload every rig's textures once, so the first loop doesn't flicker
task.spawn(function()
	local ids = {}
	for _, item in pairs(Items.Catalog) do
		local rig = rigModule(item)
		if rig and rig.preloadList then
			for _, id in ipairs(rig.preloadList()) do
				table.insert(ids, id)
			end
		end
	end
	if #ids > 0 then
		pcall(function()
			ContentProvider:PreloadAsync(ids)
		end)
	end
end)

-- worn[player][slot] = { Id, Rig, Character, Torso }
local worn: { [Player]: { [string]: any } } = {}

local function torsoOf(character: Model): BasePart?
	return (character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso")) :: BasePart?
end

local function refresh(target: Player)
	local slots = worn[target] or {}
	worn[target] = slots
	local character = target.Character
	for _, slot in ipairs(Items.Slots) do
		local id = Items.equipped(target, slot)
		local current = slots[slot]
		if current and (current.Id ~= id or current.Character ~= character or not current.Torso:IsDescendantOf(workspace)) then
			current.Rig:Destroy()
			slots[slot] = nil
			current = nil
		end
		local torso = character and torsoOf(character)
		if not current and id and torso and torso:IsDescendantOf(workspace) then
			local rig = rigModule(Items.get(id))
			if rig then
				local ok, built = pcall(rig.new, torso)
				if ok then
					slots[slot] = { Id = id, Rig = built, Character = character, Torso = torso }
				else
					warn("[Cosmetics] couldn't build " .. id .. ": " .. tostring(built))
				end
			end
		end
	end
end

local function watch(target: Player)
	for _, slot in ipairs(Items.Slots) do
		target:GetAttributeChangedSignal("Equipped" .. slot):Connect(function()
			refresh(target)
		end)
	end
	local function onCharacter(character: Model)
		-- the torso can arrive a moment after the model
		local torso = torsoOf(character)
			or character:WaitForChild("Torso", 3)
			or character:WaitForChild("UpperTorso", 3)
		if torso and target.Character == character then
			refresh(target)
		end
	end
	target.CharacterAdded:Connect(onCharacter)
	if target.Character then
		task.spawn(onCharacter, target.Character)
	end
end

for _, other in ipairs(Players:GetPlayers()) do
	watch(other)
end
Players.PlayerAdded:Connect(watch)
Players.PlayerRemoving:Connect(function(target)
	for _, w in pairs(worn[target] or {}) do
		w.Rig:Destroy()
	end
	worn[target] = nil
end)

RunService.RenderStepped:Connect(function()
	local now = os.clock()
	local camera = workspace.CurrentCamera
	local eye = camera and camera.CFrame.Position or Vector3.zero
	for target, slots in pairs(worn) do
		for slot, w in pairs(slots) do
			if not w.Torso:IsDescendantOf(workspace) then
				w.Rig:Destroy()
				slots[slot] = nil
			else
				local near = (w.Torso.Position - eye).Magnitude < CULL_DISTANCE
				w.Rig:SetEnabled(near)
				if near then
					w.Rig:Step(now)
				end
			end
		end
	end
end)

----------------------------------------------------------------------------
-- Inventory panel (only for players who own something)

local gui, panel, preview, listFrame, equipButton, nameLabel, rarityLabel, tagLabel, descLabel
local selected: string? = nil

local function corner(parent, radius)
	local c = Instance.new("UICorner")
	c.CornerRadius = UDim.new(0, radius or 8)
	c.Parent = parent
end

local function label(parent, text, size, color, font)
	local l = Instance.new("TextLabel")
	l.BackgroundTransparency = 1
	l.Text = text
	l.TextSize = size
	l.TextColor3 = color or Color3.new(1, 1, 1)
	l.Font = font or Enum.Font.GothamBold
	l.TextXAlignment = Enum.TextXAlignment.Left
	l.Size = UDim2.new(1, 0, 0, size + 4)
	l.Parent = parent
	return l
end

local function updatePanel()
	if not panel then
		return
	end
	local owned = Items.owned(player)
	if not (selected and owned[selected]) then
		selected = nil
		for id in pairs(owned) do
			selected = id
			break
		end
	end
	for _, child in ipairs(listFrame:GetChildren()) do
		if child:IsA("TextButton") then
			child:Destroy()
		end
	end
	local ids = {}
	for id in pairs(owned) do
		table.insert(ids, id)
	end
	table.sort(ids)
	for _, id in ipairs(ids) do
		local item = Items.get(id)
		local rarity = Items.Rarities[item.Rarity]
		local b = Instance.new("TextButton")
		b.Size = UDim2.new(0, 120, 1, 0)
		b.BackgroundColor3 = if id == selected then Color3.fromRGB(45, 20, 80) else Color3.fromRGB(22, 14, 40)
		b.TextColor3 = rarity and rarity.Color or Color3.new(1, 1, 1)
		b.Font = Enum.Font.GothamBold
		b.TextSize = 13
		b.Text = item.Name
		b.Parent = listFrame
		corner(b, 6)
		b.Activated:Connect(function()
			selected = id
			updatePanel()
		end)
	end

	local item = Items.get(selected)
	if not item then
		return
	end
	local rarity = Items.Rarities[item.Rarity]
	nameLabel.Text = item.Name
	rarityLabel.Text = string.upper(item.Rarity) .. "  ·  " .. string.upper(item.Category)
	rarityLabel.TextColor3 = rarity and rarity.Color or Color3.new(1, 1, 1)
	local tags = {}
	if item.Exclusive then
		table.insert(tags, "EXCLUSIVE")
	end
	if not item.ForSale then
		table.insert(tags, "NOT SOLD")
	end
	if not item.Tradeable then
		table.insert(tags, "NOT TRADEABLE")
	end
	tagLabel.Text = table.concat(tags, "  ·  ")
	descLabel.Text = item.Description or ""
	local wearing = Items.equipped(player, item.Category) == selected
	equipButton.Text = if wearing then "UNEQUIP" else "EQUIP"
	equipButton.BackgroundColor3 = if wearing then Color3.fromRGB(70, 30, 90) else Color3.fromRGB(140, 40, 220)
	if preview.Id ~= selected then
		preview:SetItem(selected)
	end
end

local function buildPanel()
	gui = Instance.new("ScreenGui")
	gui.Name = "Cosmetics"
	gui.ResetOnSpawn = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.Parent = player:WaitForChild("PlayerGui")

	local open = Instance.new("TextButton")
	open.Name = "Open"
	open.AnchorPoint = Vector2.new(0, 1)
	open.Position = UDim2.new(0, 16, 1, -150)
	open.Size = UDim2.new(0, 96, 0, 34)
	open.BackgroundColor3 = Color3.fromRGB(22, 14, 40)
	open.TextColor3 = Color3.fromRGB(255, 120, 255)
	open.Font = Enum.Font.GothamBold
	open.TextSize = 14
	open.Text = "COSMETICS"
	open.Parent = gui
	corner(open)
	local stroke = Instance.new("UIStroke")
	stroke.Color = Color3.fromRGB(180, 80, 255)
	stroke.Thickness = 1.5
	stroke.Parent = open

	panel = Instance.new("Frame")
	panel.Name = "Panel"
	panel.AnchorPoint = Vector2.new(0, 1)
	panel.Position = UDim2.new(0, 16, 1, -194)
	panel.Size = UDim2.new(0, 320, 0, 470)
	panel.BackgroundColor3 = Color3.fromRGB(10, 6, 24)
	panel.BackgroundTransparency = 0.08
	panel.Visible = false
	panel.Parent = gui
	corner(panel, 10)
	local pstroke = stroke:Clone()
	pstroke.Parent = panel
	local pad = Instance.new("UIPadding")
	pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 12), UDim.new(0, 12)
	pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 12), UDim.new(0, 12)
	pad.Parent = panel
	local layout = Instance.new("UIListLayout")
	layout.Padding = UDim.new(0, 6)
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	layout.Parent = panel

	listFrame = Instance.new("Frame")
	listFrame.BackgroundTransparency = 1
	listFrame.Size = UDim2.new(1, 0, 0, 28)
	listFrame.LayoutOrder = 1
	listFrame.Parent = panel
	local row = Instance.new("UIListLayout")
	row.FillDirection = Enum.FillDirection.Horizontal
	row.Padding = UDim.new(0, 6)
	row.Parent = listFrame

	local viewport = Instance.new("ViewportFrame")
	viewport.Size = UDim2.new(1, 0, 0, 250)
	viewport.BackgroundColor3 = Color3.fromRGB(70, 150, 210)
	viewport.LayoutOrder = 2
	viewport.Visible = false
	viewport.Parent = panel
	corner(viewport)
	preview = Preview.mount(viewport, nil)

	nameLabel = label(panel, "", 20)
	nameLabel.LayoutOrder = 3
	rarityLabel = label(panel, "", 13)
	rarityLabel.LayoutOrder = 4
	tagLabel = label(panel, "", 11, Color3.fromRGB(190, 170, 220), Enum.Font.Gotham)
	tagLabel.LayoutOrder = 5
	descLabel = label(panel, "", 12, Color3.fromRGB(220, 210, 240), Enum.Font.Gotham)
	descLabel.TextWrapped = true
	descLabel.Size = UDim2.new(1, 0, 0, 32)
	descLabel.LayoutOrder = 6

	equipButton = Instance.new("TextButton")
	equipButton.Size = UDim2.new(1, 0, 0, 36)
	equipButton.TextColor3 = Color3.new(1, 1, 1)
	equipButton.Font = Enum.Font.GothamBold
	equipButton.TextSize = 15
	equipButton.LayoutOrder = 7
	equipButton.Parent = panel
	corner(equipButton)
	equipButton.Activated:Connect(function()
		local item = Items.get(selected)
		if not item then
			return
		end
		if Items.equipped(player, item.Category) == selected then
			remote:FireServer("Unequip", item.Category)
		else
			remote:FireServer("Equip", selected)
		end
	end)

	open.Activated:Connect(function()
		panel.Visible = not panel.Visible
		viewport.Visible = panel.Visible -- the preview only animates while shown
		if panel.Visible then
			updatePanel()
		end
	end)
end

local function onOwnership()
	local any = next(Items.owned(player)) ~= nil
	if any and not gui then
		buildPanel()
	end
	if gui then
		gui.Enabled = any
		updatePanel()
	end
end

player:GetAttributeChangedSignal("OwnedCosmetics"):Connect(onOwnership)
for _, slot in ipairs(Items.Slots) do
	player:GetAttributeChangedSignal("Equipped" .. slot):Connect(updatePanel)
end
onOwnership()
]===]

local SCRIPTS = {
	{ name = "Items", class = "ModuleScript", home = "cosmetics", parent = nil },
	{ name = "VoidWings", class = "ModuleScript", home = "cosmetics", parent = nil },
	{ name = "VoidWingsData", class = "ModuleScript", home = "cosmetics", parent = "VoidWings" },
	{ name = "VoidWingsAssets", class = "ModuleScript", home = "cosmetics", parent = "VoidWings" },
	{ name = "Preview", class = "ModuleScript", home = "cosmetics", parent = nil },
	{ name = "CosmeticsServer", class = "Script", home = "server", parent = nil },
	{ name = "CosmeticsClient", class = "LocalScript", home = "client", parent = nil }
}

local recording
pcall(function()
	recording = ChangeHistoryService:TryBeginRecording("Install Void Wings")
end)

local log = {}

local function put(parent, className, name, source)
	local existing = parent:FindFirstChild(name)
	local fits = existing and (if className == "ModuleScript"
		then existing:IsA("ModuleScript")
		else existing:IsA("BaseScript"))
	if existing and not fits then
		existing.Name = name .. "_Old"
		table.insert(log, "renamed unexpected " .. existing.ClassName .. " to " .. existing:GetFullName())
		existing = nil
	end
	local script = existing or Instance.new(className)
	script.Name = name
	script.Source = source
	script.Parent = parent
	table.insert(log, (existing and "updated " or "created ") .. script:GetFullName())
	return script
end

local cosmetics = ReplicatedStorage:FindFirstChild("Cosmetics")
if cosmetics and not cosmetics:IsA("Folder") then
	cosmetics.Name = "Cosmetics_Old"
	cosmetics = nil
end
if not cosmetics then
	cosmetics = Instance.new("Folder")
	cosmetics.Name = "Cosmetics"
	cosmetics.Parent = ReplicatedStorage
	table.insert(log, "created " .. cosmetics:GetFullName())
end

if not ReplicatedStorage:FindFirstChild("CosmeticsRemote") then
	local remote = Instance.new("RemoteEvent")
	remote.Name = "CosmeticsRemote"
	remote.Parent = ReplicatedStorage
	table.insert(log, "created " .. remote:GetFullName())
end

local clientHome = StarterPlayer:FindFirstChildOfClass("StarterPlayerScripts")
	or StarterPlayer:WaitForChild("StarterPlayerScripts")
local HOMES = { cosmetics = cosmetics, server = ServerScriptService, client = clientHome }

-- keep texture ids already uploaded into this place
do
	local rig = cosmetics:FindFirstChild("VoidWings")
	local current = rig and rig:FindFirstChild("VoidWingsAssets")
	local old = current and current:IsA("ModuleScript") and current.Source or ""
	local kept = 0
	for key, id in old:gmatch('([%w_]+)%s*=%s*"(rbxassetid://%d+)"') do
		local before = SOURCES.VoidWingsAssets
		SOURCES.VoidWingsAssets = before:gsub('(%f[%w_]' .. key .. '%s*=%s*)"[^"]*"', '%1"' .. id .. '"', 1)
		if SOURCES.VoidWingsAssets ~= before then
			kept += 1
		end
	end
	for key, flag in old:gmatch('(Frame[%w_]+)%s*=%s*(%a+)') do
		if flag == "true" then
			SOURCES.VoidWingsAssets = SOURCES.VoidWingsAssets:gsub('(%f[%w_]' .. key .. '%s*=%s*)false', '%1true', 1)
		end
	end
	if kept > 0 then
		table.insert(log, "kept " .. kept .. " texture ids from your VoidWingsAssets")
	end
end

local made = {}
for _, entry in ipairs(SCRIPTS) do
	local parent = entry.parent and made[entry.parent] or HOMES[entry.home]
	made[entry.name] = put(parent, entry.class, entry.name, SOURCES[entry.name])
end

if recording then
	ChangeHistoryService:FinishRecording(recording, Enum.FinishRecordingOperation.Commit)
else
	pcall(function()
		ChangeHistoryService:SetWaypoint("Install Void Wings")
	end)
end

print("Void Wings installed:")
for _, line in ipairs(log) do
	print("  " .. line)
end
